import{_ as e,a0 as o,w as l,s,I as u,x as i,a1 as r,A as x,ao as L}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"2014年度Linux职场报告：对Linux专家的需求持续旺盛 | LCTT x X-CMD","titleTemplate":false,"description":"2014年度Linux职场报告：对Linux专家的需求持续旺盛 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2014年度Linux职场报告：对Linux专家的需求持续旺盛 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2014年度Linux职场报告：对Linux专家的需求持续旺盛 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/2014 Linux Jobs Report--Demand for Linux Expertise Drives Hiring Priorities","title":"2014年度Linux职场报告：对Linux专家的需求持续旺盛","tag":"201403","desc":""},"relativePath":"201403/2014 Linux Jobs Report--Demand for Linux Expertise Drives Hiring Priorities.md","filePath":"[post].md"}'),d={name:"201403/2014 Linux Jobs Report--Demand for Linux Expertise Drives Hiring Priorities.md"};function p(a,n,f,m,g,w){const t=o("Link");return l(),s("div",null,[n[23]||(n[23]=u("h1",{id:"_2014年度linux职场报告-对linux专家的需求持续旺盛",tabindex:"-1"},[i("2014年度Linux职场报告：对Linux专家的需求持续旺盛 "),u("a",{class:"header-anchor",href:"#_2014年度linux职场报告-对linux专家的需求持续旺盛","aria-label":"Permalink to “2014年度Linux职场报告：对Linux专家的需求持续旺盛”"},"​")],-1)),n[24]||(n[24]=u("p",null,[u("em",null,"Linux人才正在越来越多地占领人事经理的优先列表！")],-1)),n[25]||(n[25]=u("p",null,"2014年2月19日，通过对人事经理们和Linux专家的调查，2014年度职场报告正式发布，纽约和旧金山的人事经理们正跃跃欲试，计划在Linux求职市场中网罗招募更多的Linux技术人才。旺盛的需求使得Linux行业的薪资已经超过行业平均水平，并且多数Linux专家都认为Linux技术正帮助它们的职业生涯走的更长远。",-1)),n[26]||(n[26]=u("p",null,[u("img",{src:"https://www.linuxfoundation.org/sites/main/files/infogfx_jobs_report_2014.png",alt:""})],-1)),u("p",null,[n[1]||(n[1]=i("最新发布的",-1)),r(t,{href:"https://www.linuxfoundation.org/publications/linux-foundation/linux-adoption-trends-end-user-report-2014"},{default:x(()=>[...n[0]||(n[0]=[i("2014年度Linux职场报告",-1)])]),_:1}),n[2]||(n[2]=i("数据来自1100名人事经理和4000名Linux专家，从商业化职场需求，到个人的主观努力，再到吸引大多数Linux专家的工作动机，报告对Linux的职业前景进行了深入的分析观察。",-1))]),n[27]||(n[27]=L("<p>Dice董事长Shravan Goli说：“企业越来越意识到Linux正在成为商业发展的核心部分。相对的，人事经理们也正在越来越多地把offer发给拥有Linux技术的专业人才。而这些专家正在从事的项目正是企业想要洞察的未来。”</p><p>这是Dice公司和Linux基金会联合推出的第三个年度Linux职场报告。Dice是一家业内领先的专为技术和工程专家寻找工作的网站；而Linux基金会则是一个非盈利性组织，对Linux的发展和协作开发提供支持。最终发布的年度报告希望可以帮助行业人士了解Linux职业发展趋势的源头所在，同时帮助公司找到最佳途径来招聘或留住关键的Linux人才。</p><p>Linux基金会执行董事Jim Zemlin说道：“尽管对Linux人才的需求持续增长，但是市场对于经验丰富的Linux专家来说仍然有较大的人才缺口。对此，今年Linux职场报告有明确描述。同时，今年的报告表明，对于开发者和系统管理员来说，有无限的机会可以发挥自身价值或是寻求学习机会。对于Linux专家来说，未来无比光明！”</p><p>报告中的一些关键统计：</p><ul><li><strong>越来越多的人事经理计划开始招收Linux人才。</strong>77%的人事经理已经把“招聘Linux人才”列入了2014年的优先清单，去年这个比例为70%。其中9%到10%的人事经理计划半年内就要招到一位Linux专家。</li><li><strong>人事经理所要招收的Linux专家数量也在不断增加。</strong>过去6个月来，46%的人事经理扩充了他们关于Linux专家的招聘计划，这与去年2013年相比增加了3个百分点。</li><li><strong>展望Linux的工作前景。</strong>86%的Linux专家表明，Linux给了他们更多的工作机会，64%的人说他们选择Linux工作正是因为Linux在行业基础中无处不在的广泛性。</li></ul>",5)),u("p",null,[n[4]||(n[4]=i("2014年度Linux职场报告还包括：“为何现在的雇主都在寻求Linux人才”、“最能吸引Linux专家们的是什么”等等其他重要的发现，",-1)),r(t,{href:"http://techhub.dice.com/2014-DHX_linuxJobReport_LP.html"},{default:x(()=>[...n[3]||(n[3]=[i("点击这里下载完整的报告",-1)])]),_:1}),n[5]||(n[5]=i("。",-1))]),n[28]||(n[28]=u("h3",{id:"_2014年度linux职场报告统计数字",tabindex:"-1"},[i("2014年度Linux职场报告统计数字 "),u("a",{class:"header-anchor",href:"#_2014年度linux职场报告统计数字","aria-label":"Permalink to “2014年度Linux职场报告统计数字”"},"​")],-1)),n[29]||(n[29]=u("p",null,"2013年11月到12月间，Dice公司和Linux基金会同时对人事经理和Linux专家关于Linux工作中的倾向和需求进行了调查。接受调查的人事经理来自大企业、中小型公司、政府组织及相关部门，受调查总人数超过1100人，所属单位58%来自北美，21%来自欧洲，7%来自亚洲，4%来自南美，而非洲、墨西哥、中美洲和日本各占2%，中东占1%，还有不到1%来自澳大利亚、新西兰。受调查对象要求去年至少招聘了一名Linux专家，或者计划在2014年有这样的招聘计划才能接受调查，问卷调查采用多选。另外，超过4000名Linux专家接受了调查，其中34%的人表示它们作为Linux专家已经工作了10年甚至更久。",-1)),n[30]||(n[30]=u("h3",{id:"关于dice",tabindex:"-1"},[i("关于Dice "),u("a",{class:"header-anchor",href:"#关于dice","aria-label":"Permalink to “关于Dice”"},"​")],-1)),u("p",null,[n[7]||(n[7]=i("技术成就企业，而技术来源于人才。Dice能迅速为技术专家和雇主提供机会、规划与联系。了解更多，访问",-1)),r(t,{href:"http://www.dice.com/"},{default:x(()=>[...n[6]||(n[6]=[i("www.dice.com",-1)])]),_:1}),n[8]||(n[8]=i("。",-1))]),n[31]||(n[31]=u("h3",{id:"关于linux基金会",tabindex:"-1"},[i("关于Linux基金会 "),u("a",{class:"header-anchor",href:"#关于linux基金会","aria-label":"Permalink to “关于Linux基金会”"},"​")],-1)),u("p",null,[n[10]||(n[10]=i("Linux基金会是一个非营利性组织，意在推动Linux的成长和协调软件开发。成立于2000年，组织由Linux发明人Linus Torvalds发起，主要促进、保护、发展Linux操作系统，并通过分配基金会成员与开源社区资源来协调Linux软件开发。Linux基金会为合作与教育提供中立论坛，通过举办合作项目，包括LinuxCon在内的Linux会议，发起原创性研究，推动Linux标准和软件协作开发的发展。了解更多，点击",-1)),r(t,{href:"http://www.linuxfoundation.org/"},{default:x(()=>[...n[9]||(n[9]=[i("www.linuxfoundation.org",-1)])]),_:1}),n[11]||(n[11]=i("。",-1))]),n[32]||(n[32]=u("h3",{id:"",tabindex:"-1"},[u("a",{class:"header-anchor",href:"#","aria-label":"Permalink to “”"},"​")],-1)),n[33]||(n[33]=u("p",null,"注册商标：The Linux Foundation, Linux Standard Base, MeeGo, OpenDaylight, Tizen和Yocto Project都属于Linux基金会的注册商标。OpenBEL是OpenBEL集团的注册商标。Linux是Linus Torvalds的注册商标。",-1)),n[34]||(n[34]=u("hr",null,null,-1)),u("p",null,[n[13]||(n[13]=i("via: ",-1)),r(t,{href:"http://www.linuxfoundation.org/news-media/announcements/2014/02/2014-linux-jobs-report-demand-linux-expertise-drives-hiring"},{default:x(()=>[...n[12]||(n[12]=[i("http://www.linuxfoundation.org/news-media/announcements/2014/02/2014-linux-jobs-report-demand-linux-expertise-drives-hiring",-1)])]),_:1})]),u("p",null,[n[16]||(n[16]=i("译者：",-1)),r(t,{href:"http://blog.csdn.net/tinyeyeser"},{default:x(()=>[...n[14]||(n[14]=[i("Mr小眼儿",-1)])]),_:1}),n[17]||(n[17]=i(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:x(()=>[...n[15]||(n[15]=[i("wxy",-1)])]),_:1})]),u("p",null,[n[20]||(n[20]=i("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:x(()=>[...n[18]||(n[18]=[i("LCTT",-1)])]),_:1}),n[21]||(n[21]=i(" 原创翻译，",-1)),r(t,{href:"http://linux.cn/"},{default:x(()=>[...n[19]||(n[19]=[i("Linux中国",-1)])]),_:1}),n[22]||(n[22]=i(" 荣誉推出",-1))])])}const C=e(d,[["render",p]]);export{D as __pageData,C as default};
